1	package rest
2	
3	import (
4		"crypto/rand"
5		"crypto/subtle"
6		"encoding/base64"
7		"encoding/json"
8		"fmt"
9		"io"
10		"io/fs"
11		"net"
12		"net/http"
13		"os"
14		"path/filepath"
15		"regexp"
16		"strings"
17		"sync"
18		"time"
19	
20		goapi "github.com/GopeedLab/gopeed/pkg/api"
21		"github.com/GopeedLab/gopeed/pkg/base"
22		"github.com/GopeedLab/gopeed/pkg/download"
23		"github.com/GopeedLab/gopeed/pkg/mcpserver"
24		"github.com/GopeedLab/gopeed/pkg/rest/model"
25		"github.com/GopeedLab/gopeed/pkg/util"
26		"github.com/gorilla/handlers"
27		"github.com/gorilla/mux"
28		"github.com/pkg/errors"
29	)
30	
31	var (
32		runtimeMu sync.RWMutex
33	
34		Downloader *download.Downloader
35		APIService *goapi.Service
36	)
37	
38	const (
39		webAuthCookieName = "gopeed-session"
40		webAuthSessionTTL = 7 * 24 * time.Hour
41	)
42	
43	type webSessionStore struct {
44		mu       sync.Mutex
45		sessions map[string]time.Time
46		now      func() time.Time
47	}
48	
49	func newWebSessionStore() *webSessionStore {
50		return &webSessionStore{
51			sessions: make(map[string]time.Time),
52			now:      time.Now,
53		}
54	}
55	
56	func (s *webSessionStore) create() (string, time.Time, error) {
57		rawToken := make([]byte, 32)
58		if _, err := rand.Read(rawToken); err != nil {
59			return "", time.Time{}, errors.Wrap(err, "generate web session failed")
60		}
61	
62		sessionID := base64.RawURLEncoding.EncodeToString(rawToken)
63		expiresAt := s.now().Add(webAuthSessionTTL)
64	
65		s.mu.Lock()
66		defer s.mu.Unlock()
67		for existingToken, expiry := range s.sessions {
68			if !expiry.After(s.now()) {
69				delete(s.sessions, existingToken)
70			}
71		}
72		s.sessions[sessionID] = expiresAt
73		return sessionID, expiresAt, nil
74	}
75	
76	func (s *webSessionStore) valid(sessionID string) bool {
77		if sessionID == "" {
78			return false
79		}
80	
81		s.mu.Lock()
82		defer s.mu.Unlock()
83		expiresAt, ok := s.sessions[sessionID]
84		if !ok {
85			return false
86		}
87		if !expiresAt.After(s.now()) {
88			delete(s.sessions, sessionID)
89			return false
90		}
91		return true
92	}
93	
94	func Start(startCfg *model.StartConfig) (port int, err error) {
95		runtimeMu.Lock()
96		defer runtimeMu.Unlock()
97	
98		// avoid repeat start
99		if APIService != nil {
100			return apiServer.runningPort, nil
101		}
102		if startCfg == nil {
103			startCfg = &model.StartConfig{}
104		}
105		startCfg.Init()
106		if err = startCfg.Validate(); err != nil {
107			return 0, err
108		}
109		if err = initializeCore(startCfg); err != nil {
110			return 0, err
111		}
112		if startCfg.NativeMode {
113			storedConfig, configErr := Downloader.GetConfig()
114			if configErr != nil {
115				return 0, configErr
116			}
117			apiConfig := storedConfig.API
118			if apiConfig == nil {
119				apiConfig = (&base.APIServerConfig{}).Init()
120			} else {
121				apiConfig.Init()
122			}
123			startCfg.ApiEnable = &apiConfig.Enable
124			startCfg.MCPEnable = apiConfig.MCPEnable
125			startCfg.Network = apiConfig.Network
126			startCfg.Address = apiConfig.Address
127			startCfg.ApiToken = apiConfig.Token
128		}
129		if err := Downloader.ContinueOnStartup(); err != nil {
130			Downloader.Logger.Warn().Err(err).Msg("auto-start tasks failed")
131		}
132		if !startCfg.APIEnabled() {
133			return 0, nil
134		}
135		config := &base.APIServerConfig{
136			Enable:    true,
137			MCPEnable: startCfg.MCPEnable,
138			Network:   startCfg.Network,
139			Address:   startCfg.Address,
140			Token:     startCfg.ApiToken,
141		}
142		port, startErr := apiServer.startWithConfigLocked(startCfg, config)
143		if startErr != nil && startCfg.NativeMode {
144			Downloader.Logger.Error().Err(startErr).Msg("optional API server failed to start")
145			return 0, nil
146		}
147		return port, startErr
148	}
149	
150	func Stop() {
151		runtimeMu.Lock()
152		defer runtimeMu.Unlock()
153		if err := apiServer.stopLocked(); err != nil && Downloader != nil {
154			Downloader.Logger.Warn().Err(err).Msg("shutdown server failed")
155		}
156		if APIService != nil {
157			APIService.SubscribeTaskEvents(0, nil)
158		}
159		if Downloader != nil {
160			if err := Downloader.Close(); err != nil {
161				Downloader.Logger.Warn().Err(err).Msg("close downloader failed")
162			}
163		}
164		APIService = nil
165		apiServer = &apiServerManager{}
166	}
167	
168	func BuildServer(startCfg *model.StartConfig) (*http.Server, net.Listener, error) {
169		return buildServer(startCfg, true)
170	}
171	
172	func buildServer(startCfg *model.StartConfig, continueOnStartup bool) (*http.Server, net.Listener, error) {
173		if startCfg == nil {
174			startCfg = &model.StartConfig{}
175		}
176		startCfg.Init()
177		if err := startCfg.Validate(); err != nil {
178			return nil, nil, err
179		}
180	
181		if err := initializeCore(startCfg); err != nil {
182			return nil, nil, err
183		}
184	
185		if startCfg.Network == "unix" {
186			util.SafeRemove(startCfg.Address)
187		}
188	
189		listener, err := net.Listen(startCfg.Network, startCfg.Address)
190		if err != nil {
191			return nil, nil, err
192		}
193		if continueOnStartup {
194			if err := Downloader.ContinueOnStartup(); err != nil {
195				Downloader.Logger.Warn().Err(err).Msg("auto-start tasks failed")
196			}
197		}
198	
199		var r = mux.NewRouter()
200		for _, route := range APIService.RouteSpecs() {
201			route := route
202			r.Methods(route.Method).Path(route.Pattern).HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
203				body, err := io.ReadAll(r.Body)
204				if err != nil {
205					WriteJson(w, model.NewErrorResult(err.Error()))
206					return
207				}
208				response := route.Handler(&goapi.Context{
209					Method:     r.Method,
210					Path:       r.URL.Path,
211					Query:      r.URL.Query(),
212					Body:       body,
213					Headers:    r.Header,
214					PathParams: mux.Vars(r),
215				})
216				WriteStatusJson(w, response.StatusCode, response.Body)
217			})
218		}
219		if startCfg.MCPEnable {
220			r.Path("/mcp").Handler(mcpserver.NewHandler(Downloader))
221		} else {
222			r.Path("/mcp").Handler(http.NotFoundHandler())
223		}
224		// Reserve the endpoint namespace so the web UI catch-all cannot serve it.
225		r.PathPrefix("/mcp/").Handler(http.NotFoundHandler())
226	
227		enableApiToken := startCfg.ApiToken != ""
228		enableWebAuth := startCfg.WebEnable && startCfg.WebAuth != nil
229		var webSessions *webSessionStore
230		if enableWebAuth {
231			webSessions = newWebSessionStore()
232		}
233		if enableWebAuth {
234			r.Methods(http.MethodPost).Path("/api/web/login").HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
235				var loginReq model.WebAuth
236				if ReadJson(r, w, &loginReq) {
237					if loginReq.Username == startCfg.WebAuth.Username && loginReq.Password == startCfg.WebAuth.Password {
238						sessionID, expiresAt, err := webSessions.create()
239						if err != nil {
240							WriteJson(w, model.NewErrorResult(err.Error()))
241							return
242						}
243						http.SetCookie(w, &http.Cookie{
244							Name:     webAuthCookieName,
245							Value:    sessionID,
246							Path:     "/",
247							MaxAge:   int(webAuthSessionTTL.Seconds()),
248							Expires:  expiresAt,
249							HttpOnly: true,
250							Secure:   requestUsesHTTPS(r),
251							SameSite: http.SameSiteLaxMode,
252						})
253	
254						WriteJson(w, model.NewNilResult())
255						return
256					}
257				}
258				WriteStatusJson(w, http.StatusUnauthorized, model.NewErrorResult("unauthorized", model.CodeUnauthorized))
259			})
260		}
261		// Reserve the API namespace before the web file handler, including unknown
262		// endpoints and unsupported methods on otherwise known API paths.
263		r.Path("/api").Handler(http.NotFoundHandler())
264		r.PathPrefix("/api/").Handler(http.NotFoundHandler())
265		if startCfg.WebEnable {
266			r.PathPrefix("/fs/tasks").Handler(http.FileServer(new(taskFileSystem)))
267			r.PathPrefix("/fs/extensions").Handler(http.FileServer(new(extensionFileSystem)))
268			r.PathPrefix("/").Handler(gzipMiddleware(http.FileServer(newEmbedCacheFileSystem(http.FS(startCfg.WebFS)))))
269		}
270		if enableApiToken || enableWebAuth {
271			writeUnauthorized := func(w http.ResponseWriter, r *http.Request) {
272				WriteStatusJson(w, http.StatusUnauthorized, model.NewErrorResult("unauthorized", model.CodeUnauthorized))
273			}
274	
275			r.Use(func(h http.Handler) http.Handler {
276				return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
277					protectedPath := strings.HasPrefix(r.URL.Path, "/api/") || isProtectedWebFilePath(r.URL.Path) ||
278						(startCfg.MCPEnable && isMCPPath(r.URL.Path))
279					if r.URL.Path == "/api/web/login" || !protectedPath {
280						h.ServeHTTP(w, r)
281						return
282					}
283	
284					if enableApiToken {
285						// If an API token header is set, validate it before other authentication methods.
286						if provided, valid := validateAPITokenHeaders(r, startCfg.ApiToken); provided {
287							if valid {
288								h.ServeHTTP(w, r)
289								return
290							}
291	
292							writeUnauthorized(w, r)
293							return
294						}
295					}
296	
297					if enableWebAuth {
298						cookie, err := r.Cookie(webAuthCookieName)
299						if err != nil {
300							writeUnauthorized(w, r)
301							return
302						}
303						if !webSessions.valid(cookie.Value) {
304							writeUnauthorized(w, r)
305							return
306						}
307	
308						h.ServeHTTP(w, r)
309						return
310					}
311					writeUnauthorized(w, r)
312				})
313			})
314		}
315	
316		// recover panic
317		r.Use(func(h http.Handler) http.Handler {
318			return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
319				defer func() {
320					if v := recover(); v != nil {
321						err := errors.WithStack(fmt.Errorf("%v", v))
322						Downloader.Logger.Error().Stack().Err(err).Msgf("http server panic: %s %s", r.Method, r.RequestURI)
323						WriteJson(w, model.NewErrorResult(err.Error(), model.CodeError))
324					}
325				}()
326				h.ServeHTTP(w, r)
327			})
328		})
329	
330		server := &http.Server{Handler: handlers.CORS(
331			handlers.AllowedHeaders([]string{"Accept", "Content-Type", "Authorization", "X-Api-Token", "Mcp-Method", "Mcp-Name", "Mcp-Protocol-Version", "Mcp-Session-Id", "Last-Event-ID"}),
332			handlers.AllowedMethods([]string{"GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"}),
333			handlers.AllowedOrigins([]string{"*"}),
334			handlers.ExposedHeaders([]string{"Mcp-Session-Id"}),
335			handlers.AllowCredentials(),
336		)(r)}
337		return server, listener, nil
338	}
339	
340	func startConfigForAPIServer(config *base.APIServerConfig) *model.StartConfig {
341		enabled := config.Enable
342		return &model.StartConfig{
343			Network:        config.Network,
344			Address:        config.Address,
345			ApiEnable:      &enabled,
346			MCPEnable:      config.MCPEnable,
347			ApiToken:       config.Token,
348			NativeMode:     true,
349			Storage:        model.StorageMem,
350			WebEnable:      false,
351			ProductionMode: true,
352		}
353	}
354	
355	func cloneAPIServerConfig(config *base.APIServerConfig) *base.APIServerConfig {
356		if config == nil {
357			return nil
358		}
359		cloned := *config
360		return &cloned
361	}
362	
363	func sameAPIServerConfig(left, right *base.APIServerConfig) bool {
364		return left != nil && right != nil &&
365			left.Enable == right.Enable && left.MCPEnable == right.MCPEnable && left.Network == right.Network &&
366			left.Address == right.Address && left.Token == right.Token
367	}
368	
369	func validateAPITokenHeaders(r *http.Request, expected string) (provided bool, valid bool) {
370		for _, token := range r.Header.Values("X-Api-Token") {
371			provided = true
372			if constantTimeTokenEqual(strings.TrimSpace(token), expected) {
373				valid = true
374			}
375		}
376		for _, authorization := range r.Header.Values("Authorization") {
377			parts := strings.Fields(authorization)
378			if len(parts) == 0 || !strings.EqualFold(parts[0], "Bearer") {
379				continue
380			}
381			provided = true
382			if len(parts) == 2 && constantTimeTokenEqual(parts[1], expected) {
383				valid = true
384			}
385		}
386		return provided, valid
387	}
388	
389	func constantTimeTokenEqual(actual, expected string) bool {
390		return len(actual) == len(expected) && subtle.ConstantTimeCompare([]byte(actual), []byte(expected)) == 1
391	}
392	
393	func initializeCore(startCfg *model.StartConfig) error {
394		if APIService != nil {
395			return nil
396		}
397		downloadCfg := &download.DownloaderConfig{
398			ProductionMode:    startCfg.ProductionMode,
399			RefreshInterval:   startCfg.RefreshInterval,
400			WhiteDownloadDirs: startCfg.WhiteDownloadDirs,
401			WebViewProvider:   startCfg.WebViewProvider,
402		}
403		if startCfg.Storage == model.StorageBolt {
404			downloadCfg.Storage = download.NewBoltStorage(startCfg.StorageDir)
405		} else {
406			downloadCfg.Storage = download.NewMemStorage()
407		}
408		downloadCfg.StorageDir = startCfg.StorageDir
409		downloadCfg.TempDir = startCfg.TempDir
410		downloadCfg.Init()
411		Downloader = download.NewDownloader(downloadCfg)
412		if err := Downloader.Setup(); err != nil {
413			return err
414		}
415		service, err := goapi.NewService(Downloader)
416		if err != nil {
417			_ = Downloader.Close()
418			Downloader = nil
419			return err
420		}
421		APIService = service
422		return nil
423	}
424	
425	func isProtectedWebFilePath(urlPath string) bool {
426		return urlPath == "/fs" || strings.HasPrefix(urlPath, "/fs/")
427	}
428	
429	func isMCPPath(urlPath string) bool {
430		return urlPath == "/mcp" || strings.HasPrefix(urlPath, "/mcp/")
431	}
432	
433	func requestUsesHTTPS(r *http.Request) bool {
434		if r.TLS != nil {
435			return true
436		}
437		forwardedProto := strings.TrimSpace(strings.Split(r.Header.Get("X-Forwarded-Proto"), ",")[0])
