441	func resolvePath(urlPath string, prefix string) (identity string, path string, err error) {
442		// remove prefix
443		clearPath := strings.TrimPrefix(urlPath, prefix)
444		// match extension identity, eg: /fs/extensions/identity/xxx
445		reg := regexp.MustCompile(`^/([^/]+)/(.*)$`)
446		if !reg.MatchString(clearPath) {
447			err = os.ErrNotExist
448			return
449		}
450		matched := reg.FindStringSubmatch(clearPath)
451		if len(matched) != 3 {
452			err = os.ErrNotExist
453			return
454		}
455		return matched[1], matched[2], nil
456	}
