13	func Info(w http.ResponseWriter, r *http.Request) {
14		info := map[string]any{
15			"version":  base.Version,
16			"runtime":  runtime.Version(),
17			"os":       runtime.GOOS,
18			"arch":     runtime.GOARCH,
19			"inDocker": base.InDocker == "true",
