24	func Resolve(w http.ResponseWriter, r *http.Request) {
25		var req model.ResolveTask
26		if ReadJson(r, w, &req) {
27			rr, err := Downloader.Resolve(req.Req)
28			if err != nil {
29				WriteJson(w, model.NewErrorResult(err.Error()))
30				return
31			}
32			WriteJson(w, model.NewOkResult(rr))
33		}
34	}
35	
36	func CreateTask(w http.ResponseWriter, r *http.Request) {
37		var req model.CreateTask
38		if ReadJson(r, w, &req) {
39			var (
40				taskId string
41				err    error
42			)
43			if req.Rid != "" {
44				taskId, err = Downloader.CreateWithOptions(req.Rid, req.Opts)
45			} else if req.Req != nil {
46				taskId, err = Downloader.CreateDirect(req.Req, req.Opts)
47			} else {
48				WriteJson(w, model.NewErrorResult("param invalid: rid or req", model.CodeInvalidParam))
49				return
